// Isolated synthetic kernel graph benchmark. Each process validates one ABI job.
#include "hip_api.h"
#include <algorithm>
#include <fstream>
#include <memory>
#include <cmath>
#include <cstring>
#include <map>
using hip_probe::Handle;
struct Reader{std::ifstream f;Reader(const char*p):f(p,std::ios::binary){if(!f)throw std::runtime_error("job missing");}template<class T>T val(){T x;f.read((char*)&x,sizeof x);if(!f)throw std::runtime_error("job truncated");return x;}std::string str(){auto n=val<uint32_t>();std::string x(n,0);f.read(x.data(),n);return x;}};
struct Seg{uint64_t offset,bytes;std::string kind;double value;};
struct Buf{std::string id,file,kind,check;uint64_t n,checkn;double value;std::vector<Seg>segments;void*base{};void*ptr()const{return (char*)base+256;}};
static uint32_t rng=0x12345678;uint32_t next(){rng^=rng<<13;rng^=rng>>17;rng^=rng<<5;return rng;}
void fill(std::vector<unsigned char>&v,const Seg&s){if(s.offset+s.bytes>v.size())throw std::runtime_error("segment bounds");unsigned char*p=v.data()+s.offset;
 if(s.kind=="zero"){memset(p,0,s.bytes);return;}if(s.kind=="byte"){memset(p,int(s.value),s.bytes);return;}
 if(s.kind=="fp8"){int code=s.value==.25?0x28:s.value==.015625?8:s.value==1?0x38:s.value==0?0:-1;if(code<0)throw std::runtime_error("unsupported FP8 amplitude");for(size_t i=0;i<s.bytes;i++)p[i]=code?code|((next()>>31)<<7):0;return;}
 if(s.kind=="half"||s.kind=="f16"){uint16_t code=s.value==.25?0x3400:s.value==.015625?0x2400:s.value==1?0x3c00:s.value==0?0:0xffff;if(code==0xffff)throw std::runtime_error("unsupported half amplitude");for(size_t i=0;i+2<=s.bytes;i+=2){uint16_t x=code?code|((next()>>31)<<15):0;memcpy(p+i,&x,2);}return;}
 if(s.kind=="f32"){for(size_t i=0;i+4<=s.bytes;i+=4){float x=float(s.value)*(next()&1?1.f:-1.f);memcpy(p+i,&x,4);}return;}
 if(s.kind=="u32"){for(size_t i=0;i+4<=s.bytes;i+=4){uint32_t x=uint32_t(s.value);memcpy(p+i,&x,4);}return;}
 throw std::runtime_error("unknown fill "+s.kind);
}
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("jobbench JOB.BIN ROOT [launches=128] [rounds=7]");Reader r(argv[1]);if(r.val<uint32_t>()!=0x31304d4b)throw std::runtime_error("magic");std::string id=r.str(),module=r.str(),symbol=r.str(),root=argv[2];unsigned grid[3],block[3];for(auto&x:grid)x=r.val<uint32_t>();for(auto&x:block)x=r.val<uint32_t>();unsigned nb=r.val<uint32_t>();std::vector<Buf>b(nb);
 for(auto&x:b){x.id=r.str();x.n=r.val<uint64_t>();x.kind=r.str();x.value=r.val<double>();x.file=r.str();x.check=r.str();x.checkn=r.val<uint64_t>();unsigned ns=r.val<uint32_t>();for(unsigned i=0;i<ns;i++){Seg s;s.offset=r.val<uint64_t>();s.bytes=r.val<uint64_t>();s.kind=r.str();s.value=r.val<double>();x.segments.push_back(s);}}
 unsigned an=r.val<uint32_t>();std::vector<unsigned char>args(an);r.f.read((char*)args.data(),an);unsigned np=r.val<uint32_t>();struct Patch{uint32_t off,bi;uint64_t add;};std::vector<Patch>patch(np);for(auto&x:patch){x.off=r.val<uint32_t>();x.bi=r.val<uint32_t>();x.add=r.val<uint64_t>();}
 hip_probe::Api api;api.Check(api.hipInit(0),"init");api.Check(api.hipSetDevice(0),"device");Handle mod{},fn{},stream{},event0{},event1{},graph{},exec{};api.Check(api.LoadModule(&mod,(root+"/"+module).c_str()),"module");api.Check(api.hipModuleGetFunction(&fn,mod,symbol.c_str()),"function");api.Check(api.hipStreamCreate(&stream),"stream");
 for(auto&x:b){if(!x.n||x.n>2ull*1024*1024*1024)throw std::runtime_error("buffer size");api.Check(api.hipMalloc(&x.base,x.n+512),"malloc");std::vector<unsigned char>v(x.n,0);if(x.kind=="file"){std::ifstream f(root+"/"+x.file,std::ios::binary);if(!f.read((char*)v.data(),x.n))throw std::runtime_error("fixture read "+x.file);}else fill(v,Seg{0,x.n,x.kind,x.value});for(auto&s:x.segments)fill(v,s);std::vector<unsigned char>outer(x.n+512,0xa5);memcpy(outer.data()+256,v.data(),x.n);api.Check(api.hipMemcpy(x.base,outer.data(),outer.size(),1),"upload");}
 for(auto&p:patch){if(p.bi>=b.size()||p.off+8>args.size()||p.add>=b[p.bi].n)throw std::runtime_error("pointer patch bounds");void*v=(char*)b[p.bi].ptr()+p.add;memcpy(args.data()+p.off,&v,8);}
 auto launch=[&](){size_t sz=args.size();void*extra[]={(void*)1,args.data(),(void*)2,&sz,(void*)3};api.Check(api.hipModuleLaunchKernel(fn,grid[0],grid[1],grid[2],block[0],block[1],block[2],0,stream,nullptr,extra),"launch");};
 auto check=[&](){size_t guards=0,invalid=0,nonzero=0;for(auto&x:b){size_t bn0=nonzero,bi0=invalid;std::vector<unsigned char>v(x.n+512);api.Check(api.hipMemcpy(v.data(),x.base,v.size(),2),"readback");for(unsigned i=0;i<256;i++)guards+=(v[i]!=0xa5)+(v[256+x.n+i]!=0xa5);auto*p=v.data()+256;size_t count=std::min(x.checkn,x.n);if(x.check=="fp8")for(size_t i=0;i<count;i++){invalid+=(p[i]&127)==127;nonzero+=(p[i]&127)!=0;}else if(x.check=="f32")for(size_t i=0;i+4<=count;i+=4){float a;memcpy(&a,p+i,4);invalid+=!std::isfinite(a);nonzero+=a!=0;}else if(x.check=="half"||x.check=="f16")for(size_t i=0;i+2<=count;i+=2){uint16_t a;memcpy(&a,p+i,2);invalid+=(a&0x7c00)==0x7c00;nonzero+=(a&0x7fff)!=0;}if(x.check!="none")printf("BUFFER,%s,%s,invalid=%zu,nonzero=%zu\n",id.c_str(),x.id.c_str(),invalid-bi0,nonzero-bn0);}
 printf("CHECK,%s,guards=%zu,invalid=%zu,nonzero=%zu\n",id.c_str(),guards,invalid,nonzero);fflush(stdout);if(guards||invalid)throw std::runtime_error("guard/finite");if(!nonzero)throw std::runtime_error("all checked outputs zero: inspect synthetic fixture");};
 printf("START,%s,%s\n",id.c_str(),symbol.c_str());fflush(stdout);launch();api.Check(api.hipStreamSynchronize(stream),"smoke sync");check();unsigned n=argc>3?std::stoul(argv[3]):128,rounds=argc>4?std::stoul(argv[4]):7;if(!n||!rounds)throw std::runtime_error("positive counts");for(int i=0;i<8;i++)launch();api.Check(api.hipStreamSynchronize(stream),"warmup");api.EnableGraphs();api.Check(api.hipStreamBeginCapture(stream,0),"capture");for(unsigned i=0;i<n;i++)launch();api.Check(api.hipStreamEndCapture(stream,&graph),"end capture");api.Check(api.hipGraphInstantiate(&exec,graph,nullptr,nullptr,0),"instantiate");api.Check(api.hipGraphLaunch(exec,stream),"warm graph");api.Check(api.hipStreamSynchronize(stream),"graph sync");api.Check(api.hipEventCreate(&event0),"event");api.Check(api.hipEventCreate(&event1),"event");std::vector<double>times;
 for(unsigned round=0;round<rounds;round++){api.Check(api.hipEventRecord(event0,stream),"start");api.Check(api.hipGraphLaunch(exec,stream),"graph");api.Check(api.hipEventRecord(event1,stream),"end");api.Check(api.hipEventSynchronize(event1),"wait");float ms;api.Check(api.hipEventElapsedTime(&ms,event0,event1),"elapsed");times.push_back(1000.*ms/n);printf("TIME,%s,%u,%.6f\n",id.c_str(),round,times.back());}check();std::sort(times.begin(),times.end());printf("RESULT,%s,%.6f,%u,%u\n",id.c_str(),times[times.size()/2],n,rounds);api.hipGraphExecDestroy(exec);api.hipGraphDestroy(graph);for(auto&x:b)api.hipFree(x.base);api.hipEventDestroy(event0);api.hipEventDestroy(event1);api.hipStreamDestroy(stream);api.hipModuleUnload(mod);return 0;
 }catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
